"""API aplikacji "Zadania": rejestracja/logowanie (JWT), rozwiązywanie zadań, punkty i ranking."""

from datetime import datetime, timedelta, timezone

import jwt
from fastapi import Depends, FastAPI, HTTPException, status
from fastapi.security import OAuth2PasswordBearer
from passlib.context import CryptContext
from pydantic import BaseModel, Field
from sqlalchemy import (
    Boolean,
    Column,
    ForeignKey,
    Integer,
    String,
    create_engine,
)
from sqlalchemy.orm import DeclarativeBase, Session, relationship, sessionmaker

# --------------------------------------------------------------------------
# Konfiguracja
# --------------------------------------------------------------------------

SECRET_KEY = "CHANGE_ME_W_PRODUKCJI_NA_WLASNY_SEKRET"
ALGORITHM = "HS256"
ACCESS_TOKEN_EXPIRE_MINUTES = 60 * 24

ADMIN_USERNAME = "admin"
ADMIN_PASSWORD = "admin123"

SQLALCHEMY_DATABASE_URL = "sqlite:///./app.db"

pwd_context = CryptContext(schemes=["bcrypt"], deprecated="auto")
oauth2_scheme = OAuth2PasswordBearer(tokenUrl="/login")

# --------------------------------------------------------------------------
# Baza danych
# --------------------------------------------------------------------------

engine = create_engine(
    SQLALCHEMY_DATABASE_URL, connect_args={"check_same_thread": False}
)
SessionLocal = sessionmaker(autocommit=False, autoflush=False, bind=engine)


class Base(DeclarativeBase):
    pass


class User(Base):
    __tablename__ = "users"

    id = Column(Integer, primary_key=True, index=True)
    username = Column(String, unique=True, index=True, nullable=False)
    password_hash = Column(String, nullable=False)
    points = Column(Integer, default=0, nullable=False)
    is_admin = Column(Boolean, default=False, nullable=False)

    submissions = relationship(
        "Submission", back_populates="user", cascade="all, delete-orphan"
    )


class Task(Base):
    __tablename__ = "tasks"

    id = Column(Integer, primary_key=True, index=True)
    question = Column(String, nullable=False)
    answer = Column(String, nullable=False)
    points = Column(Integer, nullable=False)


class Submission(Base):
    __tablename__ = "submissions"

    id = Column(Integer, primary_key=True, index=True)
    user_id = Column(Integer, ForeignKey("users.id"), nullable=False)
    task_id = Column(Integer, ForeignKey("tasks.id"), nullable=False)
    answer = Column(String, nullable=False)
    correct = Column(Boolean, nullable=False)
    points_awarded = Column(Integer, default=0, nullable=False)
    created_at = Column(String, nullable=False)

    user = relationship("User", back_populates="submissions")
    task = relationship("Task")


def get_db():
    db = SessionLocal()
    try:
        yield db
    finally:
        db.close()


# --------------------------------------------------------------------------
# Schematy Pydantic
# --------------------------------------------------------------------------


class RegisterRequest(BaseModel):
    username: str = Field(min_length=3, max_length=50)
    password: str = Field(min_length=6, max_length=100)


class UserOut(BaseModel):
    id: int
    username: str
    points: int
    is_admin: bool

    class Config:
        from_attributes = True


class LoginRequest(BaseModel):
    username: str
    password: str


class TokenResponse(BaseModel):
    token: str


class TaskOut(BaseModel):
    id: int
    question: str
    points: int

    class Config:
        from_attributes = True


class SubmitRequest(BaseModel):
    task_id: int
    answer: str


class SubmissionOut(BaseModel):
    id: int
    user_id: int
    task_id: int
    answer: str
    correct: bool
    points_awarded: int
    created_at: str

    class Config:
        from_attributes = True


class RankingEntry(BaseModel):
    username: str
    points: int


# --------------------------------------------------------------------------
# Bezpieczeństwo: hasła i JWT
# --------------------------------------------------------------------------


def hash_password(password: str) -> str:
    return pwd_context.hash(password)


def verify_password(password: str, password_hash: str) -> bool:
    return pwd_context.verify(password, password_hash)


def create_access_token(user: User) -> str:
    expire = datetime.now(timezone.utc) + timedelta(
        minutes=ACCESS_TOKEN_EXPIRE_MINUTES
    )
    payload = {"sub": str(user.id), "username": user.username, "exp": expire}
    return jwt.encode(payload, SECRET_KEY, algorithm=ALGORITHM)


def get_current_user(
    token: str = Depends(oauth2_scheme), db: Session = Depends(get_db)
) -> User:
    credentials_exception = HTTPException(
        status_code=status.HTTP_401_UNAUTHORIZED,
        detail="Nieprawidłowy lub wygasły token",
        headers={"WWW-Authenticate": "Bearer"},
    )
    try:
        payload = jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])
        user_id = int(payload.get("sub"))
    except (jwt.PyJWTError, TypeError, ValueError):
        raise credentials_exception

    user = db.get(User, user_id)
    if user is None:
        raise credentials_exception
    return user


def get_current_admin(current_user: User = Depends(get_current_user)) -> User:
    if not current_user.is_admin:
        raise HTTPException(
            status_code=status.HTTP_403_FORBIDDEN,
            detail="Wymagane uprawnienia administratora",
        )
    return current_user


# --------------------------------------------------------------------------
# Aplikacja i dane startowe
# --------------------------------------------------------------------------

app = FastAPI(title="Zadania API")


SEED_TASKS = [
    {"question": "Ile to 2 + 2?", "answer": "4", "points": 1},
    {"question": "Stolica Polski?", "answer": "Warszawa", "points": 2},
    {"question": "Rok bitwy pod Grunwaldem?", "answer": "1410", "points": 3},
]


@app.on_event("startup")
def on_startup() -> None:
    Base.metadata.create_all(bind=engine)
    db = SessionLocal()
    try:
        if not db.query(User).filter(User.username == ADMIN_USERNAME).first():
            admin = User(
                username=ADMIN_USERNAME,
                password_hash=hash_password(ADMIN_PASSWORD),
                is_admin=True,
            )
            db.add(admin)

        if db.query(Task).count() == 0:
            for task_data in SEED_TASKS:
                db.add(Task(**task_data))

        db.commit()
    finally:
        db.close()


# --------------------------------------------------------------------------
# Endpointy
# --------------------------------------------------------------------------


@app.post("/register", response_model=UserOut, status_code=status.HTTP_201_CREATED)
def register(payload: RegisterRequest, db: Session = Depends(get_db)):
    existing = db.query(User).filter(User.username == payload.username).first()
    if existing:
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail="Użytkownik o tej nazwie już istnieje",
        )

    user = User(
        username=payload.username,
        password_hash=hash_password(payload.password),
        is_admin=False,
    )
    db.add(user)
    db.commit()
    db.refresh(user)
    return user


@app.post("/login", response_model=TokenResponse)
def login(payload: LoginRequest, db: Session = Depends(get_db)):
    user = db.query(User).filter(User.username == payload.username).first()
    if not user or not verify_password(payload.password, user.password_hash):
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Nieprawidłowa nazwa użytkownika lub hasło",
        )

    token = create_access_token(user)
    return TokenResponse(token=token)


@app.get("/tasks", response_model=list[TaskOut])
def list_tasks(
    db: Session = Depends(get_db), current_user: User = Depends(get_current_user)
):
    return db.query(Task).order_by(Task.id).all()


@app.post("/submit", response_model=SubmissionOut)
def submit_answer(
    payload: SubmitRequest,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    task = db.get(Task, payload.task_id)
    if not task:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND, detail="Zadanie nie istnieje"
        )

    is_correct = payload.answer.strip().lower() == task.answer.strip().lower()

    already_solved = (
        db.query(Submission)
        .filter(
            Submission.user_id == current_user.id,
            Submission.task_id == task.id,
            Submission.correct.is_(True),
        )
        .first()
        is not None
    )

    points_awarded = task.points if (is_correct and not already_solved) else 0

    submission = Submission(
        user_id=current_user.id,
        task_id=task.id,
        answer=payload.answer,
        correct=is_correct,
        points_awarded=points_awarded,
        created_at=datetime.now(timezone.utc).isoformat(),
    )
    db.add(submission)

    if points_awarded:
        current_user.points += points_awarded

    db.commit()
    db.refresh(submission)
    return submission


@app.get("/submissions/{submission_id}", response_model=SubmissionOut)
def get_submission(
    submission_id: int,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user),
):
    submission = db.get(Submission, submission_id)
    if not submission:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND, detail="Zgłoszenie nie istnieje"
        )

    if submission.user_id != current_user.id and not current_user.is_admin:
        raise HTTPException(
            status_code=status.HTTP_403_FORBIDDEN,
            detail="Brak dostępu do tego zgłoszenia",
        )

    return submission


@app.get("/ranking", response_model=list[RankingEntry])
def ranking(db: Session = Depends(get_db)):
    users = db.query(User).order_by(User.points.desc(), User.username.asc()).all()
    return [RankingEntry(username=u.username, points=u.points) for u in users]


@app.delete("/users/{user_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_user(
    user_id: int,
    db: Session = Depends(get_db),
    current_admin: User = Depends(get_current_admin),
):
    user = db.get(User, user_id)
    if not user:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND, detail="Użytkownik nie istnieje"
        )

    db.delete(user)
    db.commit()
    return None

