    answer: str


class SubmissionResponse(BaseModel):
    id: int
    user_id: int
    task_id: int
    answer: str
    is_correct: bool
    points_awarded: int
    created_at: datetime

    class Config:
        from_attributes = True


class RankingEntry(BaseModel):
    username: str
    points: int

    class Config:
        from_attributes = True


# --- Narzędzia pomocnicze: hasła i tokeny ---------------------------------------

def hash_password(password: str) -> str:
    return bcrypt.hashpw(password.encode("utf-8"), bcrypt.gensalt()).decode("utf-8")


def verify_password(password: str, password_hash: str) -> bool:
    return bcrypt.checkpw(password.encode("utf-8"), password_hash.encode("utf-8"))


def create_access_token(user: User) -> str:
    payload = {
        "sub": str(user.id),
        "username": user.username,
        "is_admin": user.is_admin,
        "exp": datetime.now(timezone.utc) + timedelta(minutes=ACCESS_TOKEN_EXPIRE_MINUTES),
    }
    return jwt.encode(payload, JWT_SECRET, algorithm=JWT_ALGORITHM)


# --- Dane startowe (seed) -------------------------------------------------------

def seed_data(db: Session) -> None:
    if db.query(User).filter(User.username == "admin").first() is None:
        db.add(User(username="admin", password_hash=hash_password("admin123"), is_admin=True))

    if db.query(Task).count() == 0:
        db.add_all(
            [
                Task(question="Ile to 2 + 2?", correct_answer="4", points=1),
                Task(question="Stolica Polski?", correct_answer="Warszawa", points=2),
                Task(question="Rok bitwy pod Grunwaldem?", correct_answer="1410", points=3),
            ]
        )

    db.commit()


@asynccontextmanager
async def lifespan(app: FastAPI):
    Base.metadata.create_all(bind=engine)
    db = SessionLocal()
    try:
        seed_data(db)
    finally:
        db.close()
    yield


app = FastAPI(title="Zadania API", lifespan=lifespan)


