    if task is None:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Zadanie nie istnieje")

    is_correct = payload.answer.strip().lower() == task.correct_answer.strip().lower()
    points_awarded = 0

    if is_correct:
        already_solved = (
            db.query(Submission)
            .filter(
                Submission.user_id == current_user.id,
                Submission.task_id == task.id,
                Submission.is_correct == True,  # noqa: E712
            )
            .first()
        )
        if already_solved is None:
            points_awarded = task.points
            current_user.points += points_awarded
            db.add(current_user)

    submission = Submission(
        user_id=current_user.id,
        task_id=task.id,
        answer=payload.answer,
        is_correct=is_correct,
        points_awarded=points_awarded,
    )
    db.add(submission)
    db.commit()
    db.refresh(submission)
    return submission


